FORECAST = {'list': [{'dt': 1790000000 + 10800 * i, 'main': {'temp': 285.44 - i * 0.1, 'feels_like': 284.9, 'humidity': 78}, 'weather': [{'main': 'Clouds', 'description': 'broken clouds'}]} for i in range(40)]}
