 '/index.html': '<a href="/ok.html">fine</a> <a href="/gone.html">broken</a> <a href="https://other.example/x">elsewhere</a> <a href="/ok.html#top">again</a> <a href="mailto:a@b.example">mail</a> <a>no href</a>',
